import{z as s,x as p,o as t,c as d,q as l,j as r,D as B,d as E,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"BLP 需求估计","description":"","frontmatter":{"title":"BLP 需求估计","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/blp-demand.md","filePath":"econ/blp-demand.md","lastUpdated":1791413859000}'),A={name:"econ/blp-demand.md"};function m(_,a,c,D,h,C){const i=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="blp-需求估计" tabindex="-1">BLP 需求估计 <a class="header-anchor" href="#blp-需求估计" aria-label="Permalink to &quot;BLP 需求估计&quot;">​</a></h1><div class="epigraph"><p>差异产品的价格与未观测质量一起走，logit 的价格系数有偏；用产品特征的工具和市场层份额，把随机系数需求钉在均衡上，反事实才是合并与关税，而不只是又一次回归。</p><footer>—— Berry, Levinsohn and Pakes, Automobile Prices in Market Equilibrium, Econometrica 1995</footer></div><p><a href="/econ/discrete-choice">上一课</a>在外生 \\(x\\) 下写出 logit 份额与 IIA。本课缺口是产业组织的现场：价格内生、产品差异、市场均衡。生产函数下一课换供给边的技术；本课钉 BLP 需求。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>汽车、谷物、电信套餐：产品 \\(j\\) 在市场 \\(t\\) 的份额 \\(s_{jt}\\) 来自随机系数效用</p> \\[u_{ijt}=x_{jt}\\beta_i-\\alpha_i p_{jt}+\\xi_{jt}+\\varepsilon_{ijt}, \\]<p>\\(\\xi_{jt}\\) 是厂商与消费者看见、计量者看不见的质量，与 \\(p_{jt}\\) 相关。简单 logit 把 \\(\\xi\\) 扔进误差，价格弹性偏向零（贵的车 \\(\\xi\\) 也高）。Berry 的反演：观测份额 ↔ 平均效用 \\(\\delta_{jt}\\)，于是 \\(\\xi_{jt}=\\delta_{jt}-x_{jt}\\beta+\\alpha p_{jt}\\) 可进矩。BLP：\\(\\beta_i\\) 随机，份额无闭式，用模拟；工具是其他产品的特征（成本侧排除：对手特征经竞争进价格，不进本国 \\(\\xi\\)——假设要辩护）。缺口是：估到的是需求系统，反事实（合并、关税、新产品）要与定价均衡一起解。</p><p><span class="marginnote">术语翻译：\\(\\xi_{jt}\\) 是「厂商知道、消费者感知、统计员看不见」的产品质量——品牌力、做工、口碑都算。它天然与价格正相关（好货更贵），这正是简单 logit 把价格弹性估得偏向零的病根。</span></p><p><span class="marginnote">Berry 1994 先给纯 logit 反演 \\(\\delta=\\ln s-\\ln s_0\\)。BLP 1995 加随机系数破 IIA，用收缩映射解 \\(\\delta\\)。供给边常配 Bertrand 加边际成本，不是本课必须估全，但反事实价格必须有一个供给规则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GMM：\\(\\mathbb{E}[Z\\xi]=0\\)。收缩映射在给定参数下从份额解 \\(\\delta\\)，抽 \\(\\xi\\)，进矩。随机系数分布（往往对价格、对特征的正态）决定替代：相近 \\(x\\) 的产品替代更强，红蓝公交缓解。弱工具：特征工具可以弱，第一阶段是价格对 \\(Z\\)，诊断同 IV 课。数值：收缩不收敛、模拟噪声、网格，都是实践，不是新识别。</p><p><span class="marginnote">数字实例：Berry 反演只需份额：某车 \\(s_j=0.2\\)、外选项 \\(s_0=0.8\\)，则平均效用 \\(\\delta=\\ln(0.2)-\\ln(0.8)\\approx-1.39\\)。纯 logit 到此为止；BLP 要在这个 \\(\\delta\\) 里再挖出随机系数，才需要收缩映射与模拟。</span></p>',12)),(t(),r(o,null,{default:B(()=>[n(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARE%5B%22%E8%A7%82%E6%B5%8B%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20INV%5B%22%E5%8F%8D%E6%BC%94%20%CE%B4%22%5D%0A%20%20INV%20--%3E%20XI%5B%22%CE%BE%20%3D%20%CE%B4%20%E2%88%92%20x%CE%B2%20%2B%20%CE%B1p%22%5D%0A%20%20Z%5B%22%E7%89%B9%E5%BE%81%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20GMM%5B%22E%5BZ%CE%BE%5D%3D0%22%5D%0A%20%20RC%5B%22%E9%9A%8F%E6%9C%BA%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20SUB%5B%22%E7%81%B5%E6%B4%BB%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20EQ%5B%22%E5%AE%9A%E4%BB%B7%E5%9D%87%E8%A1%A1%22%5D%20--%3E%20CF%5B%22%E5%90%88%E5%B9%B6%20%2F%20%E5%85%B3%E7%A8%8E%E5%8F%8D%E4%BA%8B%E5%AE%9E%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("与"),e("a",{href:"/econ/potential-outcomes"},"潜在结果"),E("：合并是从未观测的 \\(d\\)，LATE 没有对照。BLP 用需求+供给填表。识别失败（工具进 \\(\\xi\\)、随机系数几乎不识别）时，反事实是外推，要报告。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是两条。需求：随机系数让边际消费者的构成随价格变，弹性不是常数。供给：多产品 Bertrand 把交叉弹性送进加成。关税改到岸成本，均衡价格与份额一起动，不同于把价格当回归元的约化形式。IIA logit 的交叉弹性只跟份额成比例，合并模拟会系统错。",-1)),(t(),r(o,null,{default:B(()=>[n(i,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E4%BA%A7%E5%93%81%20j%20%E6%8F%90%E4%BB%B7%201%25%22%5D%20--%3E%20Q%7B%22%E6%B5%81%E5%A4%B1%E7%9A%84%E9%A1%BE%E5%AE%A2%E6%B5%81%E5%90%91%E5%93%AA%E9%87%8C%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%AE%80%E5%8D%95%20logit%22%7C%20PROP%5B%22%E6%8C%89%E4%BB%BD%E9%A2%9D%E6%AF%94%E4%BE%8B%E5%88%86%E7%BB%99%E6%89%80%E6%9C%89%E4%BA%A7%E5%93%81%EF%BC%88IIA%EF%BC%89%22%5D%0A%20%20Q%20--%3E%7C%22%E9%9A%8F%E6%9C%BA%E7%B3%BB%E6%95%B0%22%7C%20NEAR%5B%22%E9%9B%86%E4%B8%AD%E6%B5%81%E5%90%91%E7%89%B9%E5%BE%81%E7%9B%B8%E8%BF%91%E7%9A%84%E4%BA%A7%E5%93%81%22%5D%0A%20%20PROP%20--%3E%20ERR%5B%22%E5%90%88%E5%B9%B6%E6%A8%A1%E6%8B%9F%EF%BC%9A%E8%BF%91%E9%82%BB%E6%9B%BF%E4%BB%A3%E8%A2%AB%E4%BD%8E%E4%BC%B0%22%5D%0A%20%20NEAR%20--%3E%20OK%5B%22%E5%BC%B9%E6%80%A7%E9%9A%8F%E4%BB%B7%E6%A0%BC%E4%B8%8E%E6%B6%88%E8%B4%B9%E8%80%85%E6%9E%84%E6%88%90%E8%80%8C%E5%8F%98%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>与贸易后课：同一套需求可接到进口品种；本课先停在 IO 市场定义（城市×年），不把中国冲击写成 BLP。</p><p><span class="marginnote">Nevo 谷物、Petrin 厢型车是应用原型。工具故事（要素成本、对手特征）每篇都要重写，不能复制粘贴「BLP 工具」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估拍卖。不把收缩映射写成一定全局收缩的数学课。供给若是谈判或数量竞争，反事实换均衡概念。下一课生产函数：对象是 \\(Q=F(K,L)\\) 的技术，不是产品份额。微观需求与宏观 CES 贸易弹性不是自动同一个数。</p><p><span class="marginnote">常见误区：把 BLP 当成「更花哨的回归」。它的产出是一整套需求系统，做反事实要按新成本重新解一遍定价均衡；拿估好的系数当弹性直接外推合并效果，等于跳过了对手的重新定价反应。</span></p><p>后课默认：内生价格的差异产品用反演+工具；随机系数管替代；反事实要供给规则。不要用简单 logit 弹性去做合并模拟。排除（对手特征不进 \\(\\xi\\)）必须讲机制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\xi\\) 与价格相关 ⇒ 简单 logit 弹性偏零。</li><li>份额反演给出 \\(\\xi\\)，GMM 用特征工具。</li><li>随机系数打破 IIA，替代由特征距离驱动。</li><li>政策反事实在需求+定价均衡上重解。</li><li>出处：Berry, <em>Rand</em> 1994；Berry, Levinsohn and Pakes, <em>Econometrica</em> 1995。</li></ul>',8))])}const u=s(A,[["render",m]]);export{x as __pageData,u as default};
